<?php $status=$_GET['status']??'';$sql='SELECT r.*,b.full_name borrower,c.name category,(SELECT name FROM equipment WHERE id=r.equipment_id) equipment_name,COUNT(ri.id) quantity FROM loan_requests r JOIN borrowers b ON b.id=r.borrower_id JOIN equipment_categories c ON c.id=r.category_id LEFT JOIN request_items ri ON ri.request_id=r.id WHERE 1=1';$args=[];if(in_array($status,['Pending','Approved','Rejected','Issued','Cancelled'],true)){$sql.=' AND r.status=?';$args[]=$status;}$sql.=' GROUP BY r.id ORDER BY r.created_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();layout_start('Loan requests','requests'); ?><div class="page-heading"><div><p class="eyebrow">LENDING WORKFLOW</p><h1>Loan requests</h1><p class="muted">Review requests and check availability before approval.</p></div><a class="button primary" href="?page=request-form">＋ Create request</a></div><section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="page" value="requests"><select name="status"><option value="">All request statuses</option><?php foreach(['Pending','Approved','Rejected','Issued','Cancelled'] as $v): ?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach; ?></select><button class="button secondary">Filter</button></form><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Equipment category</th><th>Qty</th><th>Requested period</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=h($r['borrower'])?></strong></td><td><?=h($r['equipment_name']?:$r['category'])?><small class="cell-sub"><?=h($r['equipment_name']?$r['category']:'Any item in category')?><?=$r['created_by']===null?' · Online request':''?></small></td><td><?=$r['quantity']?></td><td><?=date('j M',strtotime($r['start_date']))?> – <?=date('j M Y',strtotime($r['due_date']))?></td><td><span class="badge <?=strtolower($r['status'])?>"><?=h($r['status'])?></span></td><td><a class="text-link" href="?page=request-view&id=<?=$r['id']?>">Review →</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No loan requests yet.</div><?php endif; ?></div></section><?php layout_end();
